def is_woodall(n):
    def digits_product(x):
        product = 1
        for digit in str(x):
            product *= int(digit)
        return product

    previous = []
    while n not in previous:
        previous.append(n)
        n = digits_product(n)

    return n == 1

def is_woodall(n):
    def digits_product(x):
        product = 1
        for digit in str(x):
            product *= int(digit)
        return product

    previous = set()
    while n not in previous:
        previous.add(n)
        n = digitsproduct(n)
        if n == 1:
            return True

    return False

