from sympy import primefactors

def is_woodall(n):
    return sorted(primefactors(n)) == list(range(1, len(primefactors(n))+1))

def max_difference(pairs):
    if not pairs:
        return 0
    min_price = float('inf')
    max_difference = 0
    for pair in pairs:
        min_price = min(min_price, pair[0])
        max_difference = max(max_difference, pair[1] - min_price)
    return max_difference

